#include "thesis_jaco_perception/self_mesh_geometry.hpp"
#include <diagnostic_msgs/msg/diagnostic_array.hpp>
#include <diagnostic_msgs/msg/diagnostic_status.hpp>
#include <diagnostic_msgs/msg/key_value.hpp>
#include <geometry_msgs/msg/transform_stamped.hpp>
#include <rclcpp/rclcpp.hpp>
#include <sensor_msgs/msg/point_cloud2.hpp>
#include <sensor_msgs/point_cloud2_iterator.hpp>
#include <tf2/exceptions.h>
#include <tf2_ros/buffer.h>
#include <tf2_ros/transform_listener.h>
#include <cmath>
#include <functional>

namespace thesis_jaco_perception { namespace {
constexpr char kWorld[]="world";
MeshPoint3 point(const geometry_msgs::msg::TransformStamped&t){auto&p=t.transform.translation;return {p.x,p.y,p.z};}
std::array<double,16> matrix(const geometry_msgs::msg::TransformStamped&t){auto&q=t.transform.rotation;double x=q.x,y=q.y,z=q.z,w=q.w;return {1-2*y*y-2*z*z,2*x*y-2*z*w,2*x*z+2*y*w,t.transform.translation.x,2*x*y+2*z*w,1-2*x*x-2*z*z,2*y*z-2*x*w,t.transform.translation.y,2*x*z-2*y*w,2*y*z+2*x*w,1-2*x*x-2*y*y,t.transform.translation.z,0,0,0,1};}
sensor_msgs::msg::PointCloud2 subset(const sensor_msgs::msg::PointCloud2&in,const std::vector<std::size_t>&ix){auto o=in;o.height=1;o.width=ix.size();o.row_step=o.point_step*o.width;o.data.clear();for(auto i:ix)o.data.insert(o.data.end(),in.data.begin()+i*in.point_step,in.data.begin()+(i+1)*in.point_step);return o;}
}
class MeshShadowNode:public rclcpp::Node{public:MeshShadowNode():Node("jaco_mesh_shadow_node",rclcpp::NodeOptions().enable_rosout(false).start_parameter_services(false).start_parameter_event_publisher(false)),buf_(get_clock()),listener_(buf_){epsilon_=declare_parameter<double>("epsilon_mesh_total_m",.07);input_=declare_parameter<std::string>("input_topic","/thesis/perception/points_filtered");camera_=declare_parameter<std::string>("camera_optical_frame","d435i_depth_optical_frame");xml_=declare_parameter<std::string>("robot_description","");max_age_=declare_parameter<double>("max_cloud_age_sec",.5);if(!std::isfinite(epsilon_)||epsilon_<0)throw std::invalid_argument("epsilon_mesh_total_m invalid");try{meshes_=load_collision_meshes_from_urdf_xml(xml_);}catch(const std::exception&e){load_error_=e.what();}auto q=rclcpp::SensorDataQoS().keep_last(1);sub_=create_subscription<sensor_msgs::msg::PointCloud2>(input_,q,std::bind(&MeshShadowNode::cb,this,std::placeholders::_1));self_=create_publisher<sensor_msgs::msg::PointCloud2>("/thesis/jaco_perception/mesh_shadow/points_self_confirmed",q);ext_=create_publisher<sensor_msgs::msg::PointCloud2>("/thesis/jaco_perception/mesh_shadow/points_external_candidate",q);occ_=create_publisher<sensor_msgs::msg::PointCloud2>("/thesis/jaco_perception/mesh_shadow/points_occluded_unknown",q);diag_=create_publisher<diagnostic_msgs::msg::DiagnosticArray>("/thesis/jaco_perception/mesh_shadow/diagnostics",q);}private:void report(const sensor_msgs::msg::PointCloud2&c,uint8_t level,const std::string&m){diagnostic_msgs::msg::DiagnosticStatus s;s.name="JACO2 mesh shadow";s.level=level;s.message=m;for(auto kv:std::vector<std::pair<std::string,std::string>>{{"session_only","true"},{"not_for_safety","true"},{"geometry_kind","collision_mesh"}}){diagnostic_msgs::msg::KeyValue v;v.key=kv.first;v.value=kv.second;s.values.push_back(v);}diagnostic_msgs::msg::DiagnosticArray a;a.header=c.header;a.status.push_back(s);diag_->publish(a);}void cb(const sensor_msgs::msg::PointCloud2::ConstSharedPtr c){if(c->header.frame_id!=kWorld){report(*c,2,"FRAME_NOT_WORLD");return;}if(load_error_.size()||now().seconds()-(c->header.stamp.sec+c->header.stamp.nanosec*1e-9)>max_age_){report(*c,2,"MESH_LOAD_OR_STALE_CLOUD");return;}try{auto stamp=rclcpp::Time(c->header.stamp);auto timeout=rclcpp::Duration::from_seconds(.05);auto ct=buf_.lookupTransform(kWorld,camera_,stamp,timeout);std::vector<MeshLinkTransform> ts;for(auto&m:meshes_)ts.push_back({m.link_frame,matrix(buf_.lookupTransform(kWorld,m.link_frame,stamp,timeout))});auto world=update_world_mesh_instances(meshes_,ts);std::vector<std::size_t>a,b,d;sensor_msgs::PointCloud2ConstIterator<float>x(*c,"x"),y(*c,"y"),z(*c,"z");for(std::size_t i=0;i<std::size_t(c->width)*c->height;++i,++x,++y,++z){MeshPoint3 p{*x,*y,*z};if(!is_finite(p))continue;auto h=first_world_mesh_intersection_optimized(world,point(ct),p,epsilon_);if(!h||p.x==p.x&&h->delta_ray< -epsilon_)b.push_back(i);else if(std::abs(h->delta_ray)<=epsilon_)a.push_back(i);else d.push_back(i);}self_->publish(subset(*c,a));ext_->publish(subset(*c,b));occ_->publish(subset(*c,d));report(*c,0,"MESH_SHADOW_COMPLETE");}catch(const std::exception&e){report(*c,2,std::string("TF_OR_CLOUD_FAILURE: ")+e.what());}}
double epsilon_,max_age_;std::string input_,camera_,xml_,load_error_;std::vector<MeshInstance>meshes_;tf2_ros::Buffer buf_;tf2_ros::TransformListener listener_;rclcpp::Subscription<sensor_msgs::msg::PointCloud2>::SharedPtr sub_;rclcpp::Publisher<sensor_msgs::msg::PointCloud2>::SharedPtr self_,ext_,occ_;rclcpp::Publisher<diagnostic_msgs::msg::DiagnosticArray>::SharedPtr diag_;};}
int main(int argc,char**argv){rclcpp::init(argc,argv);rclcpp::spin(std::make_shared<thesis_jaco_perception::MeshShadowNode>());rclcpp::shutdown();}
